//! Emit the `examples/all_families.rs` JSONL row schema for one measured
//! comparison: `vicinity`'s HNSW against hnswlib, the reference C++
//! implementation, and (when it builds) USearch as the native-SIMD control.
//!
//! Protocol, shared by every side:
//!
//! - clustered16 corpus (`16` centres, `sigma = 0.25`, width `96`), generated by
//!   the same `StdRng` draws as `examples/all_families.rs::generate_blobs`;
//! - all vectors L2-normalised once, so cosine and inner-product ordering agree;
//! - `k = 10`, `M = 16`, `ef_construction = 200`, one thread, sequential queries;
//! - `ef_search` swept over the same values for every side;
//! - ground truth is an untimed exact top-10 scan on the same `f32` vectors;
//! - five untimed warm-up queries, then one timed pass; recall and latency come
//!   from that same pass, exactly as `all_families::evaluate` does it.
//!
//! Run from the repository root:
//! ```text
//! cargo run --release --manifest-path tools/parity-rows/Cargo.toml -- \
//!     benchmarks/hnswlib-parity-100k.jsonl 100k
//! ```
//!
//! `build_s` is build-only for every side: no serialisation for hnswlib or
//! USearch, no snapshot writing for `vicinity`.
//!
//! `dists_per_query` is `null` on every row: `vicinity`'s counter needs the
//! `distance-stats` feature, whose atomics would slow exactly one side of the
//! comparison, and neither C++ library exposes a comparable count here.

use std::fmt::Write as _;
use std::time::Instant;

use hnswlib_sys::{HnswlibIndex, Metric};
use rand::rngs::StdRng;
use rand::{Rng, SeedableRng};
use usearch::{Index, IndexOptions, MetricKind, ScalarKind};
use vicinity::distance::DistanceMetric;
use vicinity::hnsw::HNSWIndex;

const DIM: usize = 96;
const K: usize = 10;
const CENTRES: usize = 16;
/// Dataset seed, `SEED ^ 0xC1_0000` from `all_families::generate_clustered16`.
const DATA_SEED: u64 = 0x4641_4d49_4c59 ^ 0xC1_0000;
/// HNSW graph seed, `SEED` from `all_families::build_hnsw`.
const GRAPH_SEED: u64 = 0x4641_4d49_4c59;
const SPREAD: f32 = 0.25;
const M: usize = 16;
const EF_CONSTRUCTION: usize = 200;
const EF_VALUES: &[usize] = &[10, 20, 50, 100, 200, 400];
const WARMUP: usize = 5;
const LID_SAMPLES: usize = 200;
const LID_K: usize = 10;

// ── data: the clustered16 generator from examples/all_families.rs ────────────

fn sample_raw(rng: &mut StdRng, dim: usize) -> Vec<f32> {
    (0..dim).map(|_| rng.random_range(-1.0f32..1.0)).collect()
}

fn normalize(mut v: Vec<f32>) -> Vec<f32> {
    let norm = v.iter().map(|x| x * x).sum::<f32>().sqrt();
    if norm > 1e-12 {
        for x in &mut v {
            *x /= norm;
        }
    }
    v
}

fn unit_vector(rng: &mut StdRng, dim: usize) -> Vec<f32> {
    normalize(sample_raw(rng, dim))
}

fn sample_points(
    rng: &mut StdRng,
    centres: &[Vec<f32>],
    spread: f32,
    count: usize,
) -> Vec<Vec<f32>> {
    (0..count)
        .map(|i| {
            let noise = sample_raw(rng, DIM);
            let centre = &centres[i % centres.len()];
            let mixed: Vec<f32> = centre
                .iter()
                .zip(noise.iter())
                .map(|(c, n)| c + spread * n)
                .collect();
            normalize(mixed)
        })
        .collect()
}

fn generate(n: usize, n_queries: usize) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let mut rng = StdRng::seed_from_u64(DATA_SEED);
    let centres: Vec<Vec<f32>> = (0..CENTRES).map(|_| unit_vector(&mut rng, DIM)).collect();
    let base = sample_points(&mut rng, &centres, SPREAD, n);
    let queries = sample_points(&mut rng, &centres, SPREAD, n_queries);
    (base, queries)
}

// ── exact ground truth and hardness ─────────────────────────────────────────

fn dot(a: &[f32], b: &[f32]) -> f32 {
    a.iter().zip(b.iter()).map(|(x, y)| x * y).sum()
}

fn squared_l2(a: &[f32], b: &[f32]) -> f32 {
    a.iter().zip(b.iter()).map(|(x, y)| (x - y) * (x - y)).sum()
}

/// Exact top-k by inner product, identical to `all_families::exact_top_k`.
fn exact_top_k(base: &[Vec<f32>], query: &[f32], k: usize) -> Vec<u32> {
    let mut scored: Vec<(f32, u32)> = base
        .iter()
        .enumerate()
        .map(|(i, v)| (dot(v, query), i as u32))
        .collect();
    if k < scored.len() {
        scored.select_nth_unstable_by(k - 1, |a, b| b.0.total_cmp(&a.0));
        scored.truncate(k);
    }
    scored.sort_unstable_by(|a, b| b.0.total_cmp(&a.0));
    scored.into_iter().map(|(_, id)| id).collect()
}

fn percentile(samples: &mut [f64], p: f64) -> f64 {
    if samples.is_empty() {
        return f64::NAN;
    }
    samples.sort_by(f64::total_cmp);
    let rank = ((p / 100.0) * samples.len() as f64).ceil() as usize;
    samples[rank.saturating_sub(1).min(samples.len() - 1)]
}

/// Levina-Bickel MLE, ported from `all_families::measure_hardness` (median over
/// `LID_SAMPLES` sampled base points).
fn measure_lid(base: &[Vec<f32>]) -> f64 {
    let n = base.len();
    let samples = LID_SAMPLES.min(n);
    if samples <= LID_K {
        return f64::NAN;
    }

    let mut lids: Vec<f64> = Vec::with_capacity(samples);
    for sample in 0..samples {
        let query_at = sample * n / samples;
        let query = &base[query_at];
        let mut scored: Vec<f32> = base
            .iter()
            .enumerate()
            .filter(|(index, _)| *index != query_at)
            .map(|(_, vector)| squared_l2(vector, query))
            .collect();
        scored.select_nth_unstable_by(LID_K - 1, f32::total_cmp);

        let mut distances: Vec<f64> = scored[..LID_K]
            .iter()
            .map(|squared| (f64::from(*squared)).sqrt().max(f64::MIN_POSITIVE))
            .collect();
        distances.sort_by(f64::total_cmp);
        let tenth = distances[LID_K - 1];
        let sum: f64 = distances[..LID_K - 1]
            .iter()
            .map(|distance| (distance / tenth).ln())
            .sum();
        if sum < -1e-12 {
            lids.push(-((LID_K - 1) as f64) / sum);
        }
    }
    let mut sorted = lids;
    percentile(&mut sorted, 50.0)
}

// ── rows ────────────────────────────────────────────────────────────────────

struct Row {
    family: &'static str,
    ef: usize,
    recall: f64,
    p50: f64,
    p95: f64,
    p99: f64,
    qps: f64,
    build_s: f64,
    mem_mib: Option<f64>,
    ratio: f64,
}

struct Stats {
    recall: f64,
    p50: f64,
    p95: f64,
    p99: f64,
    qps: f64,
}

/// Warm up, then time one pass over the query set, computing recall in the same
/// pass. Mirrors `all_families::evaluate`.
fn evaluate(
    search: &mut dyn FnMut(&[f32]) -> Vec<u32>,
    queries: &[Vec<f32>],
    truth: &[Vec<u32>],
) -> Stats {
    for query in queries.iter().take(WARMUP) {
        let _ = search(query);
    }

    let mut lat = Vec::with_capacity(queries.len());
    let mut hits = 0usize;
    let loop_start = Instant::now();
    for (query, truth) in queries.iter().zip(truth.iter()) {
        let start = Instant::now();
        let results = search(query);
        lat.push(start.elapsed().as_secs_f64() * 1e6);
        hits += results
            .iter()
            .take(K)
            .filter(|id| truth.iter().take(K).any(|t| t == *id))
            .count();
    }
    let total_s = loop_start.elapsed().as_secs_f64();

    Stats {
        recall: hits as f64 / (queries.len() * K) as f64,
        p50: percentile(&mut lat.clone(), 50.0),
        p95: percentile(&mut lat.clone(), 95.0),
        p99: percentile(&mut lat.clone(), 99.0),
        qps: queries.len() as f64 / total_s.max(f64::EPSILON),
    }
}

fn rows_for(
    family: &'static str,
    dataset: &Dataset,
    build_s: f64,
    mem_mib: Option<f64>,
    run: impl FnOnce(&Dataset) -> Vec<(usize, Stats)>,
) -> Vec<Row> {
    run(dataset)
        .into_iter()
        .map(|(ef, stats)| Row {
            family,
            ef,
            recall: stats.recall,
            p50: stats.p50,
            p95: stats.p95,
            p99: stats.p99,
            qps: stats.qps,
            build_s,
            mem_mib,
            ratio: dataset.exact_p50_us / stats.p50.max(f64::MIN_POSITIVE),
        })
        .collect()
}

// ── sides ───────────────────────────────────────────────────────────────────

fn run_vicinity(dataset: &Dataset) -> Result<Vec<Row>, String> {
    let start = Instant::now();
    let mut index = HNSWIndex::builder(DIM)
        .m(M)
        .ef_construction(EF_CONSTRUCTION)
        .metric(DistanceMetric::Cosine)
        .seed(GRAPH_SEED)
        .build()
        .map_err(|err| format!("vicinity builder: {err}"))?;
    for (id, vector) in dataset.base.iter().enumerate() {
        let id = u32::try_from(id).map_err(|_| "corpus does not fit in u32 ids".to_string())?;
        index
            .add_slice(id, vector)
            .map_err(|err| format!("vicinity add {id}: {err}"))?;
    }
    index
        .build()
        .map_err(|err| format!("vicinity build: {err}"))?;
    let build_s = start.elapsed().as_secs_f64();

    Ok(rows_for("hnsw", dataset, build_s, None, |dataset| {
        EF_VALUES
            .iter()
            .map(|&ef| {
                let mut search = |query: &[f32]| -> Vec<u32> {
                    index
                        .search(query, K, ef)
                        .map(|hits| hits.into_iter().map(|(id, _)| id).collect())
                        .unwrap_or_default()
                };
                (ef, evaluate(&mut search, &dataset.queries, &dataset.truth))
            })
            .collect()
    }))
}

fn run_hnswlib(dataset: &Dataset) -> Result<Vec<Row>, String> {
    let start = Instant::now();
    let mut index = HnswlibIndex::new(
        DIM,
        M,
        EF_CONSTRUCTION,
        Metric::InnerProduct,
        dataset.base.len(),
    )
    .ok_or_else(|| {
        format!(
            "hnswlib construction failed: {}",
            HnswlibIndex::last_error()
        )
    })?;
    for (id, vector) in dataset.base.iter().enumerate() {
        index
            .add(id as u64, vector)
            .map_err(|err| format!("hnswlib add {id}: {err}"))?;
    }
    let build_s = start.elapsed().as_secs_f64();

    let query_rows = EF_VALUES
        .iter()
        .map(|&ef| {
            index
                .set_ef(ef)
                .map_err(|err| format!("hnswlib set_ef {ef}: {err}"))?;
            let mut search = |query: &[f32]| -> Vec<u32> {
                index
                    .search(query, K)
                    .map(|hits| {
                        hits.into_iter()
                            .map(|(id, _)| u32::try_from(id).unwrap_or(u32::MAX))
                            .collect()
                    })
                    .unwrap_or_default()
            };
            let stats = evaluate(&mut search, &dataset.queries, &dataset.truth);
            Ok((ef, stats))
        })
        .collect::<Result<Vec<_>, String>>()?;

    Ok(rows_for("hnswlib", dataset, build_s, None, |_| query_rows))
}

fn run_usearch(dataset: &Dataset) -> Result<Vec<Row>, String> {
    let start = Instant::now();
    let options = IndexOptions {
        dimensions: DIM,
        metric: MetricKind::IP,
        quantization: ScalarKind::F32,
        connectivity: M,
        expansion_add: EF_CONSTRUCTION,
        ..Default::default()
    };
    let index = Index::new(&options).map_err(|err| format!("usearch create: {err}"))?;
    index
        .reserve_capacity_and_threads(dataset.base.len(), 1)
        .map_err(|err| format!("usearch reserve: {err}"))?;
    for (id, vector) in dataset.base.iter().enumerate() {
        index
            .add(id as u64, vector)
            .map_err(|err| format!("usearch add {id}: {err}"))?;
    }
    let build_s = start.elapsed().as_secs_f64();

    Ok(rows_for("usearch", dataset, build_s, None, |dataset| {
        EF_VALUES
            .iter()
            .map(|&ef| {
                index.change_expansion_search(ef);
                let mut search = |query: &[f32]| -> Vec<u32> {
                    index
                        .search(query, K)
                        .map(|matches| {
                            matches
                                .keys
                                .into_iter()
                                .map(|key| u32::try_from(key).unwrap_or(u32::MAX))
                                .collect()
                        })
                        .unwrap_or_default()
                };
                (ef, evaluate(&mut search, &dataset.queries, &dataset.truth))
            })
            .collect()
    }))
}

// ── dataset assembly ────────────────────────────────────────────────────────

struct Dataset {
    label: String,
    base: Vec<Vec<f32>>,
    queries: Vec<Vec<f32>>,
    truth: Vec<Vec<u32>>,
    exact_p50_us: f64,
    lid: f64,
}

fn dataset_label(n: usize) -> String {
    if n.is_multiple_of(1_000_000) {
        format!("clustered@{}m", n / 1_000_000)
    } else if n.is_multiple_of(1_000) {
        format!("clustered@{}k", n / 1_000)
    } else {
        format!("clustered@{n}")
    }
}

fn assemble(label: String, base: Vec<Vec<f32>>, queries: Vec<Vec<f32>>) -> Dataset {
    let started = Instant::now();
    let truth: Vec<Vec<u32>> = queries.iter().map(|q| exact_top_k(&base, q, K)).collect();
    eprintln!("  ground truth: {:.1}s", started.elapsed().as_secs_f64());

    let started = Instant::now();
    let lid = measure_lid(&base);
    eprintln!("  lid: {:.1}s", started.elapsed().as_secs_f64());
    let started = Instant::now();

    // Time the exact scan the same way the index queries are timed.
    for q in queries.iter().take(WARMUP) {
        let _ = exact_top_k(&base, q, K);
    }
    let mut lat = Vec::with_capacity(queries.len());
    for q in &queries {
        let t = Instant::now();
        let _ = exact_top_k(&base, q, K);
        lat.push(t.elapsed().as_secs_f64() * 1e6);
    }
    let exact_p50_us = percentile(&mut lat, 50.0);
    eprintln!(
        "  exact scan timing: {:.1}s (p50 {:.1}us)",
        started.elapsed().as_secs_f64(),
        exact_p50_us
    );

    Dataset {
        label,
        base,
        queries,
        truth,
        exact_p50_us,
        lid,
    }
}

// ── output ──────────────────────────────────────────────────────────────────

/// One-minute load average. `/proc/loadavg` is Linux-only; macOS reports the same
/// number through `sysctl -n vm.loadavg` as `"{ 1.23 1.45 1.67 }"`.
fn load_average() -> Option<f64> {
    if let Ok(text) = std::fs::read_to_string("/proc/loadavg") {
        if let Some(value) = text
            .split_whitespace()
            .next()
            .and_then(|value| value.parse::<f64>().ok())
        {
            return Some(value);
        }
    }
    let output = std::process::Command::new("sysctl")
        .args(["-n", "vm.loadavg"])
        .output()
        .ok()?;
    let text = String::from_utf8(output.stdout).ok()?;
    text.trim_matches(|c: char| c.is_whitespace() || c == '{' || c == '}')
        .split_whitespace()
        .next()
        .and_then(|value| value.parse::<f64>().ok())
}

fn write_jsonl(path: &str, rows: &[Row], dataset: &Dataset) -> std::io::Result<()> {
    fn num(value: f64, precision: usize) -> String {
        if value.is_finite() {
            format!("{value:.precision$}")
        } else {
            "null".to_string()
        }
    }
    fn mem(value: Option<f64>) -> String {
        value.map_or_else(|| "null".to_string(), |value| num(value, 1))
    }

    let mut out = String::new();
    // Provenance first: a parity row without host, cores and load1 cannot be
    // compared with a re-run, and these files are the evidence for the parity
    // claims in the README. Both field spellings are emitted because
    // `all_families`/`large_scale` write `recall_at_10`/`inverse_ratio` while
    // older parity rows were read as `recall`/`ratio`.
    let cores = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(0);
    let load1 = load_average();
    let host = std::env::var("RUNNER_OS")
        .or_else(|_| std::env::var("HOSTNAME"))
        .unwrap_or_else(|_| std::env::consts::OS.to_string());
    let _ = writeln!(
        out,
        "{{\"_meta\":true,\"schema\":1,\"harness\":\"parity-rows\",\"host\":\"{host}\",\
         \"cores\":{cores},\"load1\":{},\"n\":{},\"dim\":{DIM},\"k\":{K},\"queries\":{},\
         \"dataset\":\"{}\",\"lid\":{},\"exact_p50_us\":{},\"build\":{{\"m\":16,\
         \"ef_construction\":200}},\"vicinity\":\"working tree\"}}",
        load1.map_or_else(|| "null".to_string(), |value| format!("{value:.2}")),
        dataset.base.len(),
        dataset.queries.len(),
        dataset.label,
        num(dataset.lid, 3),
        num(dataset.exact_p50_us, 1),
    );
    for row in rows {
        let _ = writeln!(
            out,
            "{{\"family\":\"{}\",\"dataset\":\"{}\",\"knob\":\"ef_search\",\"knob_value\":{},\
             \"recall\":{},\"recall_at_10\":{},\"p50_us\":{},\"p95_us\":{},\"p99_us\":{},\
             \"qps\":{},\"dists_per_query\":null,\"build_s\":{},\"mem_mib\":{},\
             \"ratio\":{},\"inverse_ratio\":{},\"dim\":{},\"lid\":{}}}",
            row.family,
            dataset.label,
            row.ef,
            num(row.recall, 4),
            num(row.recall, 4),
            num(row.p50, 1),
            num(row.p95, 1),
            num(row.p99, 1),
            num(row.qps, 1),
            num(row.build_s, 4),
            mem(row.mem_mib),
            num(row.ratio, 4),
            num(row.ratio, 4),
            DIM,
            num(dataset.lid, 3),
        );
    }
    std::fs::write(path, out)
}

fn print_table(rows: &[Row], dataset: &Dataset, queries: usize) {
    eprintln!(
        "## {}  n={} dim={} k={} queries={} lid={:.3} exact_p50={:.1}us",
        dataset.label,
        dataset.base.len(),
        DIM,
        K,
        queries,
        dataset.lid,
        dataset.exact_p50_us
    );
    eprintln!();
    eprintln!("| family | ef | recall@10 | p50 us | p95 us | p99 us | qps | build s | ratio |");
    eprintln!("| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |");
    for row in rows {
        eprintln!(
            "| {} | {} | {:.4} | {:.1} | {:.1} | {:.1} | {:.0} | {:.2} | {:.2} |",
            row.family,
            row.ef,
            row.recall,
            row.p50,
            row.p95,
            row.p99,
            row.qps,
            row.build_s,
            row.ratio
        );
    }
    eprintln!();
}

// ── CLI ─────────────────────────────────────────────────────────────────────

fn parse_count(text: &str) -> Option<usize> {
    let text = text.trim();
    let (digits, scale) = if let Some(digits) = text.strip_suffix(['k', 'K']) {
        (digits, 1_000usize)
    } else if let Some(digits) = text.strip_suffix(['m', 'M']) {
        (digits, 1_000_000usize)
    } else {
        (text, 1usize)
    };
    digits.parse::<usize>().ok()?.checked_mul(scale)
}

fn main() {
    let mut args = std::env::args().skip(1);
    let Some(out_path) = args.next() else {
        eprintln!("usage: parity-rows <out.jsonl> [n] [queries]");
        eprintln!("       n and queries accept 100000, 100k, or 1m");
        std::process::exit(2);
    };
    let n = match args.next() {
        Some(text) => match parse_count(&text) {
            Some(n) if n > K => n,
            _ => {
                eprintln!("invalid corpus size: {text}");
                std::process::exit(2);
            }
        },
        None => 100_000,
    };
    let queries = match args.next() {
        Some(text) => match parse_count(&text) {
            Some(count) if count > 0 => count,
            _ => {
                eprintln!("invalid query count: {text}");
                std::process::exit(2);
            }
        },
        None => 500,
    };

    eprintln!("generating clustered16: n={n} dim={DIM} queries={queries}");
    let started = Instant::now();
    let (base, queries_vectors) = generate(n, queries);
    eprintln!("  generated in {:.1}s", started.elapsed().as_secs_f64());
    eprintln!("computing exact top-{K} and LID on the same vectors");
    let dataset = assemble(dataset_label(n), base, queries_vectors);

    // `PARITY_SIDES=hnsw,hnswlib` limits the run to the named sides; the 1M tier
    // uses this to skip USearch and stay inside the time budget. Default: all.
    let sides: Vec<String> = std::env::var("PARITY_SIDES").map_or_else(
        |_| vec!["hnsw".into(), "hnswlib".into(), "usearch".into()],
        |value| {
            value
                .split(',')
                .map(str::trim)
                .filter(|side| !side.is_empty())
                .map(str::to_string)
                .collect()
        },
    );
    let enabled = |side: &str| sides.iter().any(|name| name == side);
    eprintln!("sides: {}", sides.join(","));

    let mut rows = Vec::new();
    let mut failures: Vec<(&'static str, String)> = Vec::new();

    if enabled("hnsw") {
        eprintln!("building vicinity hnsw (M={M}, ef_construction={EF_CONSTRUCTION})");
        match run_vicinity(&dataset) {
            Ok(side_rows) => {
                eprintln!(
                    "  vicinity build {:.2}s, ef rows done",
                    side_rows.first().map_or(f64::NAN, |row| row.build_s)
                );
                rows.extend(side_rows);
            }
            Err(err) => failures.push(("hnsw", err)),
        }
    }

    if enabled("hnswlib") {
        eprintln!("building hnswlib (M={M}, ef_construction={EF_CONSTRUCTION})");
        match run_hnswlib(&dataset) {
            Ok(side_rows) => {
                eprintln!(
                    "  hnswlib build {:.2}s, ef rows done",
                    side_rows.first().map_or(f64::NAN, |row| row.build_s)
                );
                rows.extend(side_rows);
            }
            Err(err) => failures.push(("hnswlib", err)),
        }
    }

    if enabled("usearch") {
        eprintln!("building usearch (M={M}, ef_construction={EF_CONSTRUCTION})");
        match run_usearch(&dataset) {
            Ok(side_rows) => {
                eprintln!(
                    "  usearch build {:.2}s, ef rows done",
                    side_rows.first().map_or(f64::NAN, |row| row.build_s)
                );
                rows.extend(side_rows);
            }
            Err(err) => failures.push(("usearch", err)),
        }
    }

    for (family, reason) in &failures {
        eprintln!("side {family} failed: {reason}");
    }
    if rows.is_empty() {
        eprintln!("no rows measured");
        std::process::exit(1);
    }

    if let Err(err) = write_jsonl(&out_path, &rows, &dataset) {
        eprintln!("cannot write {out_path}: {err}");
        std::process::exit(1);
    }
    eprintln!("wrote {} rows to {out_path}", rows.len());
    eprintln!();
    print_table(&rows, &dataset, queries);
}
